/// One scheduler probe: the WAL candidate is captured before blocker rows.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FrontierProbe {
    pub candidate_lsn: String,
    pub active_xids: HashSet<u64>,
}

/// State carried between successful probes in one scheduler backend.
#[derive(Debug, Clone, Default)]
pub struct FrontierProbeState {
    pub previous_candidate_lsn: Option<String>,
    pub writer_fences: HashMap<u64, Option<String>>,
    pub last_safe_lsn: Option<String>,
}

/// Result of applying one probe to the writer-fence state.
#[derive(Debug, PartialEq, Eq)]
pub enum SafeFrontierDecision {
    AdvanceTo(String),
    HoldAt(String),
    HoldExisting,
}

/// Apply the writer-fence rule without touching PostgreSQL.
pub fn transition_writer_fences(
    state: &mut FrontierProbeState,
    probe: &FrontierProbe,
) -> Result<SafeFrontierDecision, crate::lsn::LsnParseError> {
    let candidate = crate::lsn::Lsn::parse(&probe.candidate_lsn)?;
    let previous_candidate = state
        .previous_candidate_lsn
        .as_deref()
        .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
        .transpose()?;
    let last_safe = state
        .last_safe_lsn
        .as_deref()
        .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
        .transpose()?;
    let previous_fences = state
        .writer_fences
        .iter()
        .map(|(xid, fence)| {
            Ok((
                *xid,
                fence
                    .as_deref()
                    .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
                    .transpose()?,
            ))
        })
        .collect::<Result<HashMap<_, _>, crate::lsn::LsnParseError>>()?;

    let next_fences = probe
        .active_xids
        .iter()
        .map(|xid| {
            (
                *xid,
                previous_fences
                    .get(xid)
                    .cloned()
                    .unwrap_or_else(|| previous_candidate.clone()),
            )
        })
        .collect::<HashMap<_, _>>();
    let has_unproven_fence = next_fences.values().any(Option::is_none);
    let fence_positions = next_fences.values().flatten().cloned().collect::<Vec<_>>();

    state.writer_fences = next_fences
        .iter()
        .map(|(xid, fence)| (*xid, fence.as_ref().map(|(text, _)| text.clone())))
        .collect();
    state.previous_candidate_lsn = Some(probe.candidate_lsn.clone());

    if has_unproven_fence {
        return Ok(match last_safe {
            Some((lsn, _)) => SafeFrontierDecision::HoldAt(lsn),
            None => SafeFrontierDecision::HoldExisting,
        });
    }

    let (bound_text, bound) = fence_positions
        .into_iter()
        .min_by_key(|(_, position)| position.position())
        .map_or((probe.candidate_lsn.clone(), candidate), |fence| {
            if candidate <= fence.1 {
                (probe.candidate_lsn.clone(), candidate)
            } else {
                fence
            }
        });

    let last_safe_position = last_safe.as_ref().map(|(_, position)| *position);
    let (safe, safe_position) = match last_safe {
        Some((last, position)) if position > bound => (last, position),
        _ => (bound_text, bound),
    };
    let decision = if last_safe_position == Some(safe_position) {
        SafeFrontierDecision::HoldAt(safe.clone())
    } else {
        SafeFrontierDecision::AdvanceTo(safe.clone())
    };
    state.last_safe_lsn = Some(safe);
    Ok(decision)
}

/// Pure-logic holdback classifier — no SPI calls, fully unit-testable.
///
/// Returns `true` when the frontier should be held back to prevent
/// silently skipping change-buffer rows from a long-running transaction.
///
/// # Arguments
/// - `prev_oldest_xmin`: the minimum `backend_xmin` observed at the
///   **previous** scheduler tick. `0` means "no baseline yet" (first tick
///   or holdback was just enabled).
/// - `current_oldest_xmin`: the minimum `backend_xmin` across all
///   currently in-progress transactions (regular + 2PC). `0` means
///   there are no in-progress transactions right now.
///
/// # Decision logic
/// - No in-progress transactions → safe to advance → returns `false`.
/// - First tick (no baseline) and in-progress transaction exists → hold
///   back conservatively → returns `true`.
/// - `current_oldest_xmin <= prev_oldest_xmin` → the same (or an older)
///   transaction from before the last tick is still running → returns `true`.
/// - `current_oldest_xmin > prev_oldest_xmin` → all pre-baseline
///   transactions committed; new ones are safe → returns `false`.
pub fn classify_holdback(prev_oldest_xmin: u64, current_oldest_xmin: u64) -> bool {
    if current_oldest_xmin == 0 {
        // No in-progress transactions — always safe to advance.
        return false;
    }
    if prev_oldest_xmin == 0 {
        // No baseline from previous tick; be conservative.
        return true;
    }
    // Hold back if the oldest still-running xmin is at or before the baseline.
    //
    // Note: xids are 32-bit and wrap around at ~4 billion. We treat them as
    // linear u64 here. True wraparound between two consecutive scheduler ticks
    // (100ms–10s apart) would require ~4 billion transactions to commit in that
    // window, which is impossible in practice. This assumption holds for PG18.
    current_oldest_xmin <= prev_oldest_xmin
}

thread_local! {
    static FRONTIER_PROBE_STATE: std::cell::RefCell<FrontierProbeState> =
        std::cell::RefCell::new(FrontierProbeState::default());
}

/// Probe the cluster for the current write LSN and the oldest in-progress
/// transaction xmin, then compute the safe frontier upper bound.
///
/// This performs a **single SPI round-trip** per scheduler tick.
/// The call must be made inside a `BackgroundWorker::transaction` block.
///
/// # Arguments
/// - `prev_oldest_xmin`: value from `shmem::last_tick_oldest_xmin()` —
///   the oldest xmin seen at the previous tick.
///
/// # Returns
/// `(safe_lsn, write_lsn, current_oldest_xmin, oldest_txn_age_secs)`
/// - `safe_lsn`: the LSN the frontier may safely advance to.
/// - `write_lsn`: the actual current write LSN (for holdback metric).
/// - `current_oldest_xmin`: value to persist via
///   `shmem::set_last_tick_holdback_state()` for the next tick.
/// - `oldest_txn_age_secs`: age of the oldest in-progress txn in seconds
///   (0 when no holdback is active, for the warning threshold check).
pub fn compute_safe_upper_bound(
    prev_watermark_lsn: Option<&str>,
    _prev_oldest_xmin: u64,
) -> Result<(String, String, u64, u64), PgTrickleError> {
    let probe_start = std::time::Instant::now();
    let (probe, oldest_age_secs) = Spi::connect(|client| {
        let rows = client
            .select(
                "WITH candidate AS MATERIALIZED (
                    SELECT pg_current_wal_lsn()::text AS lsn
                 ), active AS (
                    SELECT backend_xid::text::bigint AS xid,
                           EXTRACT(EPOCH FROM (now() - xact_start))::bigint AS age_secs
                    FROM pg_stat_activity
                    WHERE datname = current_database()
                      AND pid <> pg_backend_pid() AND backend_xid IS NOT NULL
                    UNION ALL
                    SELECT backend_xmin::text::bigint AS xid,
                           EXTRACT(EPOCH FROM (now() - xact_start))::bigint AS age_secs
                    FROM pg_stat_activity
                    WHERE datname = current_database()
                      AND pid <> pg_backend_pid() AND backend_xmin IS NOT NULL
                    UNION ALL
                    SELECT \"transaction\"::text::bigint AS xid,
                           EXTRACT(EPOCH FROM (now() - prepared))::bigint AS age_secs
                    FROM pg_prepared_xacts
                    WHERE database = current_database()
                 )
                 SELECT candidate.lsn, active.xid::text, active.age_secs::text
                 FROM candidate LEFT JOIN active ON TRUE",
                None,
                &[],
            )
            .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                context: "frontier probe".to_string(),
                reason: e.to_string(),
            })?;

        let mut candidate_lsn = None;
        let mut active_xids = HashSet::new();
        let mut oldest_age_secs = 0_u64;
        for row in rows {
            let candidate = row
                .get::<String>(1)
                .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                    context: "frontier probe candidate".to_string(),
                    reason: e.to_string(),
                })?
                .ok_or_else(|| PgTrickleError::SafeFrontierUnavailable {
                    context: "frontier probe candidate".to_string(),
                    reason: "candidate LSN was NULL".to_string(),
                })?;
            if !is_valid_lsn(&candidate) {
                return Err(PgTrickleError::SafeFrontierUnavailable {
                    context: "frontier probe candidate".to_string(),
                    reason: format!("malformed candidate LSN '{candidate}'"),
                });
            }
            candidate_lsn = Some(candidate);

            let xid =
                row.get::<String>(2)
                    .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                        context: "frontier probe xid".to_string(),
                        reason: e.to_string(),
                    })?;
            if let Some(xid) = xid {
                let xid =
                    xid.parse::<u64>()
                        .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                            context: "frontier probe xid".to_string(),
                            reason: format!("malformed transaction ID '{xid}': {e}"),
                        })?;
                active_xids.insert(xid);
                let age = row
                    .get::<String>(3)
                    .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                        context: "frontier probe transaction age".to_string(),
                        reason: e.to_string(),
                    })?
                    .ok_or_else(|| PgTrickleError::SafeFrontierUnavailable {
                        context: "frontier probe transaction age".to_string(),
                        reason: "transaction age was NULL".to_string(),
                    })?
                    .parse::<u64>()
                    .map_err(|e| PgTrickleError::SafeFrontierUnavailable {
                        context: "frontier probe transaction age".to_string(),
                        reason: e.to_string(),
                    })?;
                oldest_age_secs = oldest_age_secs.max(age);
            }
        }

        Ok::<_, PgTrickleError>((
            FrontierProbe {
                candidate_lsn: candidate_lsn.ok_or_else(|| {
                    PgTrickleError::SafeFrontierUnavailable {
                        context: "frontier probe".to_string(),
                        reason: "probe returned no rows".to_string(),
                    }
                })?,
                active_xids,
            },
            oldest_age_secs,
        ))
    })?;
    crate::shmem::record_holdback_probe(probe_start.elapsed().as_millis() as u64, false);
    if let Some(previous) = prev_watermark_lsn {
        crate::lsn::Lsn::parse(previous).map_err(|e| PgTrickleError::SafeFrontierUnavailable {
            context: "previous frontier watermark".to_string(),
            reason: format!("malformed LSN '{previous}': {e}"),
        })?;
    }
    let write_lsn = probe.candidate_lsn.clone();
    let current_oldest_xmin = probe.active_xids.iter().copied().min().unwrap_or(0);
    let decision = FRONTIER_PROBE_STATE.with(|state| {
        let mut state = state.borrow_mut();
        let mut next_state = (*state).clone();
        if next_state.last_safe_lsn.is_none()
            && let Some(previous) = prev_watermark_lsn
        {
            next_state.last_safe_lsn = Some(previous.to_string());
        }
        let decision = transition_writer_fences(&mut next_state, &probe).map_err(|e| {
            PgTrickleError::SafeFrontierUnavailable {
                context: "frontier probe state".to_string(),
                reason: format!("malformed LSN in holdback state: {e}"),
            }
        })?;
        *state = next_state;
        Ok::<_, PgTrickleError>(decision)
    })?;
    let safe_lsn = match decision {
        SafeFrontierDecision::AdvanceTo(lsn) | SafeFrontierDecision::HoldAt(lsn) => lsn,
        SafeFrontierDecision::HoldExisting => {
            return Err(PgTrickleError::SafeFrontierUnavailable {
                context: "frontier probe".to_string(),
                reason: "active transaction has no proven prior fence".to_string(),
            });
        }
    };

    Ok((safe_lsn, write_lsn, current_oldest_xmin, oldest_age_secs))
}

fn is_valid_lsn(lsn: &str) -> bool {
    crate::lsn::Lsn::parse(lsn).is_ok()
}

